package asicen

// streamSetup is the fixed initialization input that selects the USB
// backend's stream setup through the BDA driver's key expansion.
var streamSetup = [16]byte{
	0xaf, 0x49, 0xfd, 0x49, 0x0f, 0x26, 0x7c, 0x10,
	0x59, 0xc8, 0xe9, 0x43, 0xed, 0x4f, 0x74, 0xa5,
}

// transportSeed is the expected IC setup after initialization.
var transportSeed = [16]byte{
	0x00, 0x00, 0x08, 0x00, 0x00, 0x01, 0xc0, 0x04,
	0x00, 0x00, 0xc0, 0xa6, 0x00, 0x00, 0x01, 0x00,
}
